from django.conf import settings
from django.contrib.auth import authenticate
from django.contrib.auth.models import User
from django.core.exceptions import ObjectDoesNotExist
from django.http import HttpResponse
from django.shortcuts import redirect, render
from django.urls import reverse
from django.views import View
from django.views.generic import TemplateView
from django.views.generic.edit import FormView
from two_factor import views as two_factor_views
from two_factor.forms import AuthenticationTokenForm
from two_factor.models import Token
from two_factor.utils import get_token_model

from .forms import TwoFactorSetupForm

# Set the TOTP secret key
from two_factor import settings as two_factor_settings
two_factor_settings.TOTP_SECRET = "12345678901234567890"

# Set the TOTP length
from two_factor import settings as two_factor_settings
two_factor_settings.TOTP_LENGTH = 6

# Set the TOTP time step
from two_factor import settings as two_factor_settings
two_factor_settings.TOTP_TIME_STEP = 30

# Set the TOTP algorithm
from two_factor import settings as two_factor_settings
two_factor_settings.TOTP_ALGORITHM = "SHA1"

# Set the TOTP issuer name
from two_factor import settings as two_factor_settings
two_factor_settings.TOTP_ISSUER_NAME = "MyApp"


class TwoFactorSetupView(FormView):
    template_name = "two_factor/setup.html"
    form_class = TwoFactorSetupForm
    success_url = "/"

    def get_context_data(self, **kwargs):
        context = super().get_context_data(**kwargs)
        context["user"] = self.request.user
        return context

    def form_valid(self, form):
        user = self.request.user
        secret = form.cleaned_data["secret"]
        token = Token.objects.create(user=user, key=secret)
        return redirect("two_factor:setup_complete")

    def form_invalid(self, form):
        return self.render_to_response(self.get_context_data(form=form))


class TwoFactorSetupCompleteView(TemplateView):
    template_name = "two_factor/setup_complete.html"

    def get_context_data(self, **kwargs):
        context = super().get_context_data(**kwargs)
        context["user"] = self.request.user
        return context


class TwoFactorAuthenticationView(two_factor_views.LoginView):
    template_name = "two_factor/login.html"

    def get_context_data(self, **kwargs):
        context = super().get_context_data(**kwargs)
        context["user"] = self.request.user
        return context

    def form_valid(self, form):
        user = authenticate(username=form.cleaned_data["username"], password=form.cleaned_data["password"])
        if user is not None:
            # Check if user has a token
            try:
                token = get_token_model().objects.get(user=user)
            except ObjectDoesNotExist:
                token = None
            if token is not None:
                # Check if the token is valid
                if token.verify_token(form.cleaned_data["token"]):
                    # Log in the user
                    self.request.user = user
                    self.request.session["user_id"] = user.id
                    return redirect("two_factor:setup_complete")
            else:
                return redirect("two_factor:setup")
        return super().form_valid(form)


