XML_FILE_PATH = os.path.join(os.getcwd(), "pytest-results.xml")

# The namespace used by NUnit3
NAMESPACE = "http://nunit.org/ns/xunit/2.4"


def write_xml_result(results, file_path):
    """Write the test results to an XML file in NUnit3 format."""
    root = ET.Element("test-run", attrib={"name": "pytest", "start-time": datetime.now().isoformat(), "end-time": datetime.now().isoformat()})

    for result in results:
        test_case = ET.SubElement(root, "test-case", attrib={"name": result["name"], "classname": "pytest", "result": result["status"]})

        if result["status"] == "passed":
            ET.SubElement(test_case, "outcome", attrib={"result": "passed"})

        elif result["status"] == "failed":
            ET.SubElement(test_case, "failure", attrib={"message": result["message"], "type": result["type"]})

        elif result["status"] == "skipped":
            ET.SubElement(test_case, "skipped", attrib={"reason": result["message"]})

        if result["duration"]:
            ET.SubElement(test_case, "duration", attrib={"seconds": str(result["duration"])})

    tree = ET.ElementTree(root)
    tree.write(file_path, encoding="utf-8", xml_declaration=True)


def pytest_runtest_logreport(report):
    """Handle pytest log reports and write NUnit3 XML results."""
    if report.failed:
        write_xml_result(
            [
                {
                    "name": report.location[2],
                    "status": "failed",
                    "message": report.longreprtext,
                    "type": "AssertionError",
                    "duration": report.duration,
                }
            ],
            XML_FILE_PATH,
        )

    elif report.passed:
        write_xml_result(
            [
                {
                    "name": report.location[2],
                    "status": "passed",
                    "duration": report.duration,
                }
            ],
            XML_FILE_PATH,
        )

    elif report.skipped:
        write_xml_result(
            [
                {
                    "name": report.location[2],
                    "status": "skipped",
                    "message": report.longreprtext,
                    "duration": report.duration,
                }
            ],
            XML_FILE_PATH,
        )


def pytest_terminal_summary(terminalreporter, exitstatus, config):
    """Write the final XML file with all test results."""
    results = []

    for report in terminalreporter.stats.get("passed", []):
        results.append(
            {
                "name": report.location[2],
                "status": "passed",
                "duration": report.duration,
            }
        )

    for report in terminalreporter.stats.get("failed", []):
        results.append(
