                "name": report.location[2],
                "status": "failed",
                "message": report.longreprtext,
                "type": "AssertionError",
                "duration": report.duration,
            }
        )

    for report in terminalreporter.stats.get("skipped", []):
        results.append(
            {
                "name": report.location[2],
                "status": "skipped",
                "message": report.longreprtext,
                "duration": report.duration,
            }
        )

