from django.contrib import admin
from django.contrib.auth.models import User
from django.contrib.auth.forms import AuthenticationForm
from django.contrib.auth import authenticate, login
from django.http import HttpResponseRedirect
from django.urls import reverse
from django.template.response import TemplateResponse
from django.utils.html import format_html
from django.utils.safestring import mark_safe
from django import forms
from django.utils.translation import gettext_lazy as _


class CustomAuthenticationForm(AuthenticationForm):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.fields['username'].widget.attrs['class'] = 'form-control'
        self.fields['password'].widget.attrs['class'] = 'form-control'


class UserAdmin(admin.ModelAdmin):
    form = CustomAuthenticationForm

    def get_urls(self):
        urls = super().get_urls()
        custom_urls = [
            (
                r'^(?P<user_id>\d+)/login/$', 
                self.admin_site.admin_view(self.login_as_user),
                'login_as_user'
            ),
        ]
        return custom_urls + urls

    def login_as_user(self, request, user_id):
        user = User.objects.get(pk=user_id)
        if request.method == 'POST':
            form = self.form(request, data=request.POST)
            if form.is_valid():
                username = form.cleaned_data['username']
                password = form.cleaned_data['password']
                user_to_login = User.objects.get(username=username)
                if authenticate(username=username, password=password):
                    login(request, user_to_login)
                    return HttpResponseRedirect(reverse('admin:index'))
                else:
                    form.add_error(None, 'Invalid username or password')
        else:
            form = self.form(request)
        context = dict(
            self.admin_site.each_context(request),
            form=form,
            user=user,
        )
        return TemplateResponse(request, 'admin/login_as_user.html', context)

    def change_view(self, request, object_id, form_url='', extra_context=None):
        extra_context = extra_context or {}
        user = User.objects.get(pk=object_id)
        extra_context['login_button'] = format_html(
            '<a class="btn btn-primary" href="{}">Log in as user</a>',
            reverse('admin:user_user-login', args=[object_id])
        )
        return super().change_view(request, object_id, form_url, extra_context)

    def get_form(self, request, obj=None, **kwargs):
        form = super().get_form(request, obj, **kwargs)
        form.base_fields['password'].help_text = ''
        return form


admin.site.unregister(User)
admin.site.register(User, UserAdmin)

