class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)
    is_admin = db.Column(db.Boolean, default=False)

class Model(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.datetime.utcnow)
    last_modified = db.Column(db.DateTime, default=datetime.datetime.utcnow)
    version = db.Column(db.String(20), default='1.0.0')
    status = db.Column(db.String(20), default='active')
    user = db.relationship('User', backref=db.backref('models', lazy=True))

class TestResult(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    model_id = db.Column(db.Integer, db.ForeignKey('model.id'), nullable=False)
    test_name = db.Column(db.String(100), nullable=False)
    result = db.Column(db.String(100), nullable=False)
    timestamp = db.Column(db.DateTime, default=datetime.datetime.utcnow)
    model = db.relationship('Model', backref=db.backref('test_results', lazy=True))

class Deployment(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    model_id = db.Column(db.Integer, db.ForeignKey('model.id'), nullable=False)
    version = db.Column(db.String(20), default='1.0.0')
    status = db.Column(db.String(20), default='active')
    timestamp = db.Column(db.DateTime, default=datetime.datetime.utcnow)
    model = db.relationship('Model', backref=db.backref('deployments', lazy=True))

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']

def extract_zip(zip_path, extract_path):
    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        zip_ref.extractall(extract_path)

def generate_unique_name(prefix):
    return f"{prefix}_{uuid.uuid4().hex}"

def get_model_path(model_name, version):
    return os.path.join(app.config['MODEL_FOLDER'], f"{model_name}_{version}")

