def get_deployment_path(model_name, version):
    return os.path.join(app.config['DEPLOY_FOLDER'], f"{model_name}_{version}")

def run_tests(model_name, model_version):
    model_path = get_model_path(model_name, model_version)
    test_path = get_test_path(model_name, model_version)
    os.makedirs(test_path, exist_ok=True)
    test_files = [f for f in os.listdir(model_path) if f.endswith('.py')]
    for test_file in test_files:
        test_file_path = os.path.join(model_path, test_file)
        test_result_path = os.path.join(test_path, f"test_{test_file}")
        with open(test_result_path, 'w') as f:
