    deployment_path = get_deployment_path(model_name, model_version)
    os.makedirs(deployment_path, exist_ok=True)
    shutil.copytree(model_path, deployment_path)
    deployment = Deployment(model_id=model.id, version=model_version)
    db.session.add(deployment)
    db.session.commit()

