import git
import os
import re
import subprocess
import sys

class GitDataManagementSystem:
    def __init__(self, repo_path):
        self.repo_path = repo_path
        self.repo = git.Repo(repo_path)

    def clone_repo(self, url):
        try:
            self.repo = git.Repo.clone_from(url, self.repo_path)
            print("Repository cloned successfully.")
        except git.exc.GitCommandError as e:
            print(f"Error cloning repository: {e}")
            sys.exit(1)

    def checkout_branch(self, branch_name):
        try:
            self.repo.git.checkout(branch_name)
            print(f"Switched to branch '{branch_name}'.")
        except git.exc.GitCommandError as e:
            print(f"Error checking out branch '{branch_name}': {e}")
            sys.exit(1)

    def create_branch(self, branch_name):
        try:
            self.repo.git.checkout("-b", branch_name)
            print(f"Created and switched to branch '{branch_name}'.")
        except git.exc.GitCommandError as e:
            print(f"Error creating branch '{branch_name}': {e}")
            sys.exit(1)

    def commit_changes(self, message):
        try:
            self.repo.git.add(".")
            self.repo.git.commit("-m", message)
            print("Changes committed.")
        except git.exc.GitCommandError as e:
            print(f"Error committing changes: {e}")
            sys.exit(1)

    def push_changes(self, branch_name):
        try:
            self.repo.git.push("origin", branch_name)
            print(f"Changes pushed to branch '{branch_name}'.")
        except git.exc.GitCommandError as e:
            print(f"Error pushing changes to branch '{branch_name}': {e}")
            sys.exit(1)

    def pull_changes(self, branch_name):
        try:
            self.repo.git.pull("origin", branch_name)
            print(f"Changes pulled from branch '{branch_name}'.")
        except git.exc.GitCommandError as e:
            print(f"Error pulling changes from branch '{branch_name}': {e}")
            sys.exit(1)

    def merge_branches(self, source_branch, target_branch):
        try:
            self.repo.git.checkout(target_branch)
            self.repo.git.merge(source_branch)
