FIREBASE_CLIENT_ID = os.environ.get("FIREBASE_CLIENT_ID")
FIREBASE_AUTH_URI = os.environ.get("FIREBASE_AUTH_URI")
FIREBASE_TOKEN_URI = os.environ.get("FIREBASE_TOKEN_URI")
FIREBASE_AUTH_PROVIDER_X509_CERT_URL = os.environ.get("FIREBASE_AUTH_PROVIDER_X509_CERT_URL")
FIREBASE_CLIENT_X509_CERT_URL = os.environ.get("FIREBASE_CLIENT_X509_CERT_URL")

# Function to generate an access token for Firebase
def get_access_token():
    headers = {
        "content-type": "application/x-www-form-urlencoded"
    }
    data = {
        "grant_type": "urn:ietf:params:oauth:grant-type:jwt-bearer",
        "assertion": generate_jwt_token()
    }
    response = requests.post(FIREBASE_TOKEN_URI, headers=headers, data=data)
    response.raise_for_status()
    return response.json()["access_token"]

# Function to generate a JWT token for Firebase
def generate_jwt_token():
    payload = {
        "iss": FIREBASE_CLIENT_EMAIL,
        "scope": "https://www.googleapis.com/auth/firebase.database https://www.googleapis.com/auth/firebase.messaging https://www.googleapis.com/auth/firebase.firestore",
        "aud": FIREBASE_TOKEN_URI,
        "exp": int((datetime.utcnow() + timedelta(minutes=60)).timestamp()),
        "iat": int(datetime.utcnow().timestamp())
    }
    return base64.urlsafe_b64encode(
        base64.urlsafe_b64encode(json.dumps(payload).encode()).decode().replace("=", "")
    ).decode().replace("=", "")

